REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO v_document_management_runtime;
DO $$ BEGIN EXECUTE format('REVOKE CONNECT,CREATE,TEMPORARY ON DATABASE %I FROM PUBLIC',current_database()); END $$;
DO $$ BEGIN EXECUTE format('GRANT CONNECT ON DATABASE %I TO v_document_management_runtime,v_document_management_migration',current_database()); END $$;
GRANT SELECT,INSERT ON "document_template","template_version","file_object","training_contract","contract_signed_copy","training_document","document_version","state_event","operation_receipt","evidence_checkpoint" TO v_document_management_runtime;
GRANT UPDATE("kind","name","active_version_id","revision") ON "document_template" TO v_document_management_runtime;
GRANT UPDATE("template_id","version_no","status","file_id","created_by") ON "template_version" TO v_document_management_runtime;
GRANT UPDATE("storage_key","purpose","sha256","byte_length","media_type","scan_status","uploaded_by","uploaded_at") ON "file_object" TO v_document_management_runtime;
GRANT UPDATE("enrollment_id","student_id","template_version_id","generated_file_id","basis_file_id","basis_schema_version","status","replaces_contract_id","generated_by","generated_at","revision") ON "training_contract" TO v_document_management_runtime;
GRANT UPDATE("contract_id","copy_no","file_id","is_current","declared_signed_at","recorded_at","recorded_by","basis") ON "contract_signed_copy" TO v_document_management_runtime;
GRANT UPDATE("enrollment_id","kind","revision","current_version_id") ON "training_document" TO v_document_management_runtime;
GRANT UPDATE("document_id","enrollment_id","version_no","template_version_id","evidence_snapshot_id","dependency_revision","evidence_status","rendered_file_id","basis_file_id","basis_schema_version","renderer_version","state","revision","generated_by","generated_at") ON "document_version" TO v_document_management_runtime;
GRANT UPDATE("template_id","template_version_id","signed_copy_id","action","contract_id","document_id","document_version_id","sequence_no","from_state","to_state","actor_id","occurred_at","reason","command_id") ON "state_event" TO v_document_management_runtime;
GRANT UPDATE(status,template_id,template_version_id,contract_id,document_id,document_version_id,outcome_code,completed_at) ON operation_receipt TO v_document_management_runtime;
GRANT UPDATE(dependency_revision,last_change_id,observed_at) ON evidence_checkpoint TO v_document_management_runtime;
GRANT EXECUTE ON FUNCTION dm_require_file(uuid,uuid,text),dm_activate_template(uuid,uuid,uuid,bigint) TO v_document_management_runtime;
DO $secure$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend dep WHERE dep.classid='pg_proc'::regclass AND dep.objid=p.oid AND dep.deptype='e') LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,public,pg_temp',f.signature);
 END LOOP;
END $secure$;
ALTER TABLE "document_template" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON "document_template" TO v_document_management_runtime USING (school_id=nullif(current_setting('vairas.school_id',true),'')::uuid) WITH CHECK (school_id=nullif(current_setting('vairas.school_id',true),'')::uuid);
